package com.careerpilot.backend.modules.discovery.adapters.in.web;
import com.careerpilot.backend.modules.discovery.domain.*; import com.careerpilot.backend.modules.discovery.services.*; import com.careerpilot.connector.sdk.*; import org.springframework.http.*; import org.springframework.web.bind.annotation.*; import java.util.*;
@RestController @RequestMapping("/api/v1/connectors") public class ConnectorController { private final ConnectorRegistry registry;private final DiscoveryScheduler scheduler;public ConnectorController(ConnectorRegistry r,DiscoveryScheduler s){registry=r;scheduler=s;}public record RegisterRequest(String connectorId,boolean enabled){}@PostMapping("/register")public ResponseEntity<ConnectorRegistration> register(@RequestBody RegisterRequest x){Connector c=registry.get(x.connectorId());c.setEnabled(x.enabled());return ResponseEntity.status(HttpStatus.CREATED).body(registry.enable(x.connectorId(),x.enabled()));}@GetMapping public List<ConnectorRegistration> list(){return registry.list();}@GetMapping("/{id}")public ConnectorRegistration get(@PathVariable String id){return registry.list().stream().filter(x->x.getId().equals(id)).findFirst().orElseThrow();}@PostMapping("/{id}/discover")public SynchronizationResult discover(@PathVariable String id){return scheduler.trigger(id);}@PostMapping("/discover-all")public List<SynchronizationResult> all(){return scheduler.triggerAll();}}
